import{_ as t,o,c as d,a2 as a}from"./chunks/framework.Dx-TCpNt.js";const m=JSON.parse('{"title":"Development & Customization","description":"This section is for people who want to change KomaYomi rather than just use it: add a panel detector, adjust the folder scanner, publish a custom export…","frontmatter":{"description":"This section is for people who want to change KomaYomi rather than just use it: add a panel detector, adjust the folder scanner, publish a custom export…"},"headers":[],"relativePath":"development/index.md","filePath":"development/index.md","lastUpdated":1794778149000}'),r={name:"development/index.md"};function s(n,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="development-customization" tabindex="-1">Development &amp; Customization <a class="header-anchor" href="#development-customization" aria-label="Permalink to &quot;Development &amp; Customization&quot;">​</a></h1><p>This section is for people who want to change KomaYomi rather than just use it: add a panel detector, adjust the folder scanner, publish a custom export style, or work on the app itself. Every statement here was checked against the source; when this section and the code disagree, the code is right.</p><p>If you only want to read manga and take notes, the <a href="/KomaYomi-docs/guide/introduction">Guide</a> is the better place to start.</p><h2 id="what-is-in-this-section" tabindex="-1">What is in this section <a class="header-anchor" href="#what-is-in-this-section" aria-label="Permalink to &quot;What is in this section&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Answers</th></tr></thead><tbody><tr><td>This page</td><td>How the frontend, server and shared layer fit together, and what only the local build can do.</td></tr><tr><td><a href="/KomaYomi-docs/development/data-formats">Data formats</a></td><td>The JSON envelope, page documents, <code>library.json</code>, <code>.mnproj</code>, <code>.mntpl</code>, <code>.mnexp</code>, migrations and unknown-field rules.</td></tr><tr><td><a href="/KomaYomi-docs/development/plugins">Panel plugins</a></td><td>The actual plugin contract, working examples, how to test one, and the error codes.</td></tr><tr><td><a href="/KomaYomi-docs/development/folder-rules">Folder rules</a></td><td>Placeholders, optional segments, wildcards, <code>ignore</code>, <code>extensions</code>, and complete examples for common folder layouts.</td></tr><tr><td><a href="/KomaYomi-docs/development/export-templates">Export templates</a></td><td>Every field a template can store, a complete <code>.mnexp</code>, and how to apply it.</td></tr><tr><td><a href="/KomaYomi-docs/development/build">Build &amp; packaging</a></td><td>Dev server, production build, standalone server, Electron, Docker and the static online edition.</td></tr><tr><td><a href="/KomaYomi-docs/development/contributing">Contributing</a></td><td>Branch model, commit messages, lint/typecheck/test commands, and a minimal feature change.</td></tr></tbody></table><h2 id="repository-map" tabindex="-1">Repository map <a class="header-anchor" href="#repository-map" aria-label="Permalink to &quot;Repository map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>src/</code></td><td>React 18 frontend: library sidebar, panel workbench, compare reader, notes, export dialog, dialogs and i18n strings.</td></tr><tr><td><code>server/</code></td><td>Node HTTP API and every local capability: library scan, panel detection, layouts, plugins, alignment presets, export, backup, storage, version history.</td></tr><tr><td><code>shared/</code></td><td>Code used by both sides: domain types, the JSON envelope and migrations, panel ordering, Markdown rendering.</td></tr><tr><td><code>electron/</code></td><td>Electron main process and data-directory handling.</td></tr><tr><td><code>scripts/</code></td><td>Batch CLI (<code>manga-cli.ts</code>), server bundler, i18n scanner, detection baseline.</td></tr><tr><td><code>plugins/</code></td><td>Optional panel plugins. A user can also put them in <code>data/plugins/</code>.</td></tr><tr><td><code>docs/</code></td><td>This VitePress site (its own <code>package.json</code>).</td></tr><tr><td><code>raw/</code>, <code>data/</code>, <code>exports/</code></td><td>Your images, your JSON, your generated output. None of them is committed.</td></tr></tbody></table><h2 id="the-three-layers" tabindex="-1">The three layers <a class="header-anchor" href="#the-three-layers" aria-label="Permalink to &quot;The three layers&quot;">​</a></h2><h3 id="frontend-—-src" tabindex="-1">Frontend — <code>src/</code> <a class="header-anchor" href="#frontend-—-src" aria-label="Permalink to &quot;Frontend — `src/`&quot;">​</a></h3><p>A single-page React app built by Vite. <code>src/App.tsx</code> holds the shell (top bar, sidebar, stage, notes column, pane splitters); feature components live in <code>src/components/</code>. <code>src/api.ts</code> is the only place that talks to the backend: every call is a <code>fetch</code> to a relative <code>/api/...</code> path, so the frontend never knows whether it is served by Vite, the standalone server or Electron.</p><p>State that belongs to the server — the library, the current page document, saved templates — is loaded through <code>src/api.ts</code> and written back explicitly. There is no local database in the browser during normal use.</p><h3 id="server-—-server" tabindex="-1">Server — <code>server/</code> <a class="header-anchor" href="#server-—-server" aria-label="Permalink to &quot;Server — `server/`&quot;">​</a></h3><p>One routing function, <code>createMangaHandler({ rootDir })</code> in <code>server/app.ts</code>, checks <code>pathname</code> and <code>method</code> and delegates to a domain module. The same handler runs in three hosts:</p><table tabindex="0"><thead><tr><th>Host</th><th>Entry point</th><th>How it is reached</th></tr></thead><tbody><tr><td>Dev and preview</td><td><code>server/plugin.ts</code></td><td>Vite middleware on <code>127.0.0.1:5173</code>; no second process.</td></tr><tr><td>Standalone / Docker</td><td><code>server/standalone.ts</code></td><td><code>npm start</code> on port <code>3921</code>, with <code>RAW_DIR</code>, <code>DATA_DIR</code>, <code>EXPORT_DIR</code> overrides.</td></tr><tr><td>Desktop</td><td><code>dist-server/app.mjs</code></td><td>Bundled by <code>scripts/build-server.mjs</code> and loaded by <code>electron/main.cjs</code>.</td></tr></tbody></table><p>Modules are deliberately narrow: <code>library.ts</code> scans and groups pages, <code>dirRules.ts</code> turns path patterns into page records, <code>detect.ts</code> is the XY-cut detector, <code>plugins.ts</code> runs plugin scripts, <code>layouts.ts</code> expands declarative grids, <code>storage.ts</code> owns page reads and writes, <code>schemaStore.ts</code> owns schema migration and atomic writes, <code>export.ts</code> and <code>exportDocx.ts</code> render documents, <code>project.ts</code> and <code>backup.ts</code> handle packages and ZIPs.</p><h3 id="shared-—-shared" tabindex="-1">Shared — <code>shared/</code> <a class="header-anchor" href="#shared-—-shared" aria-label="Permalink to &quot;Shared — `shared/`&quot;">​</a></h3><p><code>shared/</code> must stay free of Node-only and DOM-only APIs so both sides can import it.</p><table tabindex="0"><thead><tr><th>File</th><th>What it holds</th></tr></thead><tbody><tr><td><code>types.ts</code></td><td><code>PageDoc</code>, <code>Panel</code>, <code>Note</code>, <code>Annotation</code>, reading directions, export config, library types.</td></tr><tr><td><code>format.ts</code></td><td>The <code>$schema</code> / <code>schemaVersion</code> envelope, per-format validation, migration dispatch, <code>preserveUnknown</code>.</td></tr><tr><td><code>migrations.ts</code></td><td>Pure v0 → v1 migration functions, no disk access.</td></tr><tr><td><code>panelOrder.ts</code></td><td>Reading order and group ordering used by display, export and CLI.</td></tr><tr><td><code>markdown.ts</code></td><td>Markdown rendering with raw HTML escaped.</td></tr><tr><td><code>schemas/*.json</code></td><td>Readable JSON Schema mirrors; the runtime validator is the source of truth.</td></tr></tbody></table><h2 id="how-a-request-travels" tabindex="-1">How a request travels <a class="header-anchor" href="#how-a-request-travels" aria-label="Permalink to &quot;How a request travels&quot;">​</a></h2><p><strong>Reading the library.</strong> The sidebar calls <code>GET /api/library</code>. <code>server/app.ts</code> receives it, <code>server/library.ts</code> reads <code>data/library.json</code>, resolves rules through <code>server/dirRules.ts</code>, walks <code>raw/</code> (or a mapped remote root), groups images into volumes → chapters → pages, and returns JSON. Nothing is written.</p><p><strong>Saving a page.</strong> The workbench calls <code>PUT /api/page</code> with the whole page document. <code>server/app.ts</code> validates the basic shape, then <code>writePageDoc</code> in <code>server/storage.ts</code>:</p><ol><li>refuses to touch a file written by a newer schema (<code>409</code>, <code>ERR_SCHEMA_TOO_NEW</code>);</li><li>normalizes rectangles, notes, offsets and ids;</li><li>merges unknown fields from the previous version with <code>preserveUnknown</code>;</li><li>writes atomically through <code>server/schemaStore.ts</code>;</li><li>records a version snapshot unless the caller asked to skip it.</li></ol><p><strong>Detecting panels.</strong> <code>POST /api/detect</code> tries a layout template bound to the page, chapter or volume, then the first matching plugin, then the built-in detector. The result is written back with <code>detectSource</code> and <code>detectorVersion</code>, so you can tell later where the boxes came from.</p><h2 id="local-only-capabilities" tabindex="-1">Local-only capabilities <a class="header-anchor" href="#local-only-capabilities" aria-label="Permalink to &quot;Local-only capabilities&quot;">​</a></h2><p>The desktop and local-server builds have capabilities the static online edition does not, because they need filesystem and process access:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Local web / desktop</th><th>Static online edition</th></tr></thead><tbody><tr><td>Scan a folder under <code>raw/</code></td><td>Yes</td><td>No — the browser cannot walk a folder tree.</td></tr><tr><td>Automatic panel detection</td><td>Yes</td><td>Not ported yet.</td></tr><tr><td>Layout templates and plugins</td><td>Yes</td><td>No — both run in the server process.</td></tr><tr><td>WebDAV / network storage and image cache</td><td>Yes</td><td>No.</td></tr><tr><td>Backup ZIP, project import/export</td><td>Yes</td><td>Project files can be opened; no folder backup.</td></tr><tr><td>Where work is stored</td><td><code>data/</code> next to your images</td><td>IndexedDB in the browser</td></tr></tbody></table><p>The static edition lives in a separate repository and is still in development. Its source is <code>https://github.com/PayayaKamo/KomaYomi-online</code>; this repository builds the local edition only. See <a href="/KomaYomi-docs/development/build#the-static-online-edition">Build &amp; packaging</a> for what is shared and what is not.</p><h2 id="conventions-worth-knowing" tabindex="-1">Conventions worth knowing <a class="header-anchor" href="#conventions-worth-knowing" aria-label="Permalink to &quot;Conventions worth knowing&quot;">​</a></h2><ul><li>The server is plain ESM TypeScript and is run directly by Node&#39;s type stripping in development; imports include the <code>.ts</code> extension.</li><li>There is no database. Every persisted value is a JSON file, written atomically.</li><li>User-facing strings in the server live in <code>server/messages/catalog.ts</code>; frontend strings live in <code>src/i18n/</code>. Adding a hard-coded Chinese string to a component is treated as a bug by <code>npm run i18n:scan</code>.</li><li>The documentation site is three isomorphic locales. A new page needs <code>docs/&lt;page&gt;.md</code>, <code>docs/zh/&lt;page&gt;.md</code> and <code>docs/ja/&lt;page&gt;.md</code>, plus nav and sidebar entries in <code>docs/.vitepress/config.mts</code>.</li></ul><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ul><li>Changing how pages are found on disk: <a href="/KomaYomi-docs/development/folder-rules">Folder rules</a>.</li><li>Replacing the detector for one magazine: <a href="/KomaYomi-docs/development/plugins">Panel plugins</a>.</li><li>Writing a tool that reads or writes KomaYomi data: <a href="/KomaYomi-docs/development/data-formats">Data formats</a>.</li><li>Changing the app itself: <a href="/KomaYomi-docs/development/contributing">Contributing</a>.</li></ul>',31)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
